#include <bits/stdc++.h>
using namespace std;

int main() {
    string A;
    cin >> A;
    int n = A.size();

    // nxt[i][c] = next occurrence of c at position >= i, or n if not found
    vector<array<int,26>> nxt(n+1);
    for (int c = 0; c < 26; c++) nxt[n][c] = n; // not found
    for (int i = n-1; i >= 0; i--) {
        for (int c = 0; c < 26; c++) nxt[i][c] = nxt[i+1][c];
        nxt[i][A[i]-'a'] = i;
    }

    // dp[i] = length of shortest non-subsequence of A[i..n-1]
    vector<int> dp(n+2);
    dp[n] = 1; // any single char is not subseq of empty
    for (int i = n-1; i >= 0; i--) {
        // For each char c:
        // if nxt[i][c] == n: not found, cost = 1
        // else: cost = 1 + dp[nxt[i][c]+1]
        dp[i] = INT_MAX;
        for (int c = 0; c < 26; c++) {
            int val;
            if (nxt[i][c] == n) val = 1;
            else val = 1 + dp[nxt[i][c]+1];
            dp[i] = min(dp[i], val);
        }
    }

    // Reconstruct
    string result = "";
    int pos = 0;
    while (pos <= n) {
        // Find smallest c achieving dp[pos]
        for (int c = 0; c < 26; c++) {
            int val;
            if (nxt[pos][c] == n) val = 1;
            else val = 1 + dp[nxt[pos][c]+1];
            if (val == dp[pos]) {
                result += (char)('a' + c);
                if (nxt[pos][c] == n) {
                    // done
                    goto done;
                }
                pos = nxt[pos][c] + 1;
                break;
            }
        }
    }
    done:

    cout << result << endl;
    return 0;
}

