#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string A;
    cin >> A;
    int n = (int)A.size();

    const int ALPHA = 26;
    const int INF = 1e9;

    // nextPos[i][c] = smallest position >= i where character c appears, or n if none.
    vector<array<int, ALPHA>> nextPos(n + 1);
    for (int c = 0; c < ALPHA; ++c) nextPos[n][c] = n;

    for (int i = n - 1; i >= 0; --i) {
        nextPos[i] = nextPos[i + 1];
        nextPos[i][A[i] - 'a'] = i;
    }

    // dp[i] = length of shortest string that is NOT a subsequence of A starting from position i
    // i means we may use only A[i..n-1].
    vector<int> dp(n + 1, INF);
    vector<int> choice(n + 1, -1);

    dp[n] = 1; // any single character is not a subsequence of empty string
    for (int i = n; i >= 0; --i) {
        if (i == n) {
            choice[i] = 0; // 'a' is lexicographically smallest
            continue;
        }

        for (int c = 0; c < ALPHA; ++c) {
            int p = nextPos[i][c];
            int cand;
            if (p == n) {
                cand = 1; // this character itself is impossible as subsequence
            } else {
                cand = 1 + dp[p + 1];
            }

            if (cand < dp[i] || (cand == dp[i] && c < choice[i])) {
                dp[i] = cand;
                choice[i] = c;
            }
        }
    }

    // Reconstruct answer from state 0.
    string ans;
    int i = 0;
    while (true) {
        int c = choice[i];
        ans.push_back(char('a' + c));
        int p = nextPos[i][c];
        if (p == n) break; // done: current string is not a subsequence
        i = p + 1;
    }

    cout << ans << '\n';
    return 0;
}

#include <stdio.h>
#include <string.h>

int main() {
    char A[200005];
    scanf("%s", A);
    int n = strlen(A);

    // next[i][c] = smallest index >= i where A[index] == c, or -1 if none
    // We'll compute this from right to left
    // nxt[i][c]: for position i (0-indexed), next occurrence of c at or after i

    static int nxt[200005][26];

    // Initialize for i = n
    for (int c = 0; c < 26; c++) nxt[n][c] = -1;

    for (int i = n-1; i >= 0; i--) {
        for (int c = 0; c < 26; c++) nxt[i][c] = nxt[i+1][c];
        nxt[i][A[i]-'a'] = i;
    }

    // dp[i] = min length of non-subsequence of A[i..n-1]
    static int dp[200005];
    dp[n] = 1; // any single char is not a subsequence of empty string

    for (int i = n-1; i >= 0; i--) {
        int best = -1; // we want min dp[next+1], where if no next, value = 0
        for (int c = 0; c < 26; c++) {
            int val;
            if (nxt[i][c] == -1) {
                val = 0;
            } else {
                val = dp[nxt[i][c] + 1];
            }
            if (best == -1 || val < best) best = val;
        }
        dp[i] = 1 + best;
    }

    // Reconstruct: greedily pick lexicographically smallest char at each step
    char ans[200005];
    int pos = 0;
    int cur = 0; // current position in A
    int target = dp[0];

    for (int step = 0; step < target; step++) {
        // We need dp[cur] == target - step
        // Pick smallest c such that it contributes to dp[cur]
        int needed = (target - step) - 1; // dp value we need after this char
        for (int c = 0; c < 26; c++) {
            int val;
            if (nxt[cur][c] == -1) val = 0;
            else val = dp[nxt[cur][c]+1];

            if (val == needed) {
                ans[pos++] = 'a' + c;
                if (nxt[cur][c] == -1) {
                    // done, this char not in remaining A
                    goto done;
                }
                cur = nxt[cur][c] + 1;
                break;
            }
        }
    }
    done:
    ans[pos] = '\0';
    printf("%s\n", ans);
    return 0;
}

