int main() {
    char A[1000001];
    scanf("%s", A);

    int n = strlen(A);
    int seen[26] = {0};
    int count = 0;
    char last_missing = 'a';

    for (int i = 0; i < n; i++) {
        int idx = A[i] - 'a';
        if (!seen[idx]) {
            seen[idx] = 1;
            count++;
        }
        if (count == 26) {
            // Reset for next block
            memset(seen, 0, sizeof(seen));
            count = 0;
            last_missing = A[i]; // last char of this complete block
        }
    }

    // Find smallest missing letter after last block
    for (char c = 'a'; c <= 'z'; c++) {
        if (!seen[c - 'a']) {
            printf("%c%c\n", last_missing, c);
            return 0;
        }
    }

    return 0;
}

