int main(void) {
    char *A = (char *)malloc(200005 * sizeof(char));
    if (!A) return 0;
    if (scanf("%200000s", A) != 1) return 0;

    int n = (int)strlen(A);

    /* nextPos[i][c] = smallest index >= i where character c appears, or -1 */
    int (*nextPos)[26] = malloc((n + 2) * sizeof(*nextPos));
    int *dp = malloc((n + 2) * sizeof(int));
    int *choice = malloc((n + 2) * sizeof(int));
    if (!nextPos || !dp || !choice) return 0;

    for (int c = 0; c < 26; c++) nextPos[n][c] = -1;

    for (int i = n - 1; i >= 0; i--) {
        for (int c = 0; c < 26; c++) nextPos[i][c] = nextPos[i + 1][c];
        nextPos[i][A[i] - 'a'] = i;
    }

    /* dp[i] = length of shortest string that is NOT a subsequence of A[i..n-1] */
    dp[n] = 1;
    choice[n] = 0; /* arbitrary */

    for (int i = n - 1; i >= 0; i--) {
        int bestLen = 1 << 30;
        int bestChar = 0;

        for (int c = 0; c < 26; c++) {
            int p = nextPos[i][c];
            int cand;
            if (p == -1) {
                cand = 1;
            } else {
                cand = 1 + dp[p + 1];
            }

            if (cand < bestLen || (cand == bestLen && c < bestChar)) {
                bestLen = cand;
                bestChar = c;
            }
        }

        dp[i] = bestLen;
        choice[i] = bestChar;
    }

    char *ans = malloc((dp[0] + 1) * sizeof(char));
    if (!ans) return 0;

    int pos = 0, idx = 0;
    while (1) {
        int c = choice[pos];
        ans[idx++] = (char)('a' + c);

        int p = nextPos[pos][c];
        if (p == -1) break;
        pos = p + 1;
        if (idx >= dp[0]) break;
    }
    ans[idx] = '\0';

    printf("%s\n", ans);

    free(A);
    free(nextPos);
    free(dp);
    free(choice);
    free(ans);
    return 0;
}

import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String A = sc.next();
        int n = A.length();

        int[][] next = new int[n + 1][26];
        for (int i = n - 1; i >= 0; i--) {
            for (int c = 0; c < 26; c++) {
                next[i][c] = next[i + 1][c];
            }
            next[i][A.charAt(i) - 'a'] = i + 1; // 1-indexed: position after matching
        }
        // next[i][c] = 0 means no occurrence of c at position >= i

        String[] best = new String[n + 2];
        best[0] = "";
        Queue<Integer> queue = new LinkedList<>();
        queue.add(0);
        String answer = null;

        while (!queue.isEmpty() && answer == null) {
            int pos = queue.poll();
            for (int c = 0; c < 26; c++) {
                int nxt = next[pos][c];
                String cand = best[pos] + (char)('a' + c);
                if (nxt == 0) { // no such character
                    if (answer == null || cand.compareTo(answer) < 0) answer = cand;
                } else if (best[nxt] == null) {
                    best[nxt] = cand;
                    queue.add(nxt);
                }
            }
        }
        System.out.println(answer);
    }
}

