                    count++;
                    seen = new boolean[26];
                    lastRound = new StringBuilder();
                }
            }
        }

        // Find the smallest missing letter in the last incomplete round
        for (char c = 'a'; c <= 'z'; c++) {
            if (!seen[c - 'a']) {
                System.out.println(lastRound.toString() + c);
                return;
            }
        }
