import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String A = br.readLine().trim();
        int n = A.length();

        // nextPos[i][c] = smallest index >= i where character c appears, or -1 if none
        int[][] nextPos = new int[n + 2][26];
        for (int c = 0; c < 26; c++) nextPos[n][c] = -1;

        for (int i = n - 1; i >= 0; i--) {
            System.arraycopy(nextPos[i + 1], 0, nextPos[i], 0, 26);
            nextPos[i][A.charAt(i) - 'a'] = i;
        }

        // dp[i] = length of shortest string that is NOT a subsequence of A starting from position i
        // Meaning: considering suffix A[i...n-1], what is the shortest absent subsequence?
        int[] dp = new int[n + 1];
        dp[n] = 1; // any single character is not a subsequence of empty string

        for (int i = n - 1; i >= 0; i--) {
            int best = Integer.MAX_VALUE;
            for (int c = 0; c < 26; c++) {
                int p = nextPos[i][c];
                if (p == -1) {
                    best = 1;
                    break;
                } else {
                    best = Math.min(best, 1 + dp[p + 1]);
                }
            }
            dp[i] = best;
        }

        // Reconstruct lexicographically smallest answer of length dp[0]
        StringBuilder ans = new StringBuilder();
        int pos = 0;
        while (true) {
            for (int c = 0; c < 26; c++) {
                int p = nextPos[pos][c];
                if (p == -1) {
                    ans.append((char) ('a' + c));
                    System.out.println(ans.toString());
                    return;
                } else if (dp[pos] == 1 + dp[p + 1]) {
                    ans.append((char) ('a' + c));
                    pos = p + 1;
                    break;
                }
            }
        }
    }
}
